    const existing=latest.libraryBooks.find(book=>book.id===result.book!.id);
    const book:LibraryBook=existing?{...result.book,...existing,inReadingLibrary:true,...(destination!==null?{folderId}:{})}:{...result.book,folderId,inReadingLibrary:true};
    const libraryBooks=existing?latest.libraryBooks.map(item=>item.id===book.id?book:item):[...latest.libraryBooks,book];
    if(await saveRef.current({...latest,libraryBooks},existing?'已加入读书书架':'书籍已导入')){
     setSelectedFolder(destination===null?null:folderId||'');switchBook(book.id);
    }else setReaderError('书籍信息未能保存，请等当前保存完成后重新导入。');
